        while ($line =~ /\b([a-zA-Z_]\w*)\.([a-zA-Z_]\w*)\s*\(/g) {
            my ($alias, $callee) = ($1, $2);
            next unless exists $imports{$alias};
            record_call($imports{$alias}, $callee, $caller, $file);
        }

        if ($local_import_path =~ m{/internal(/|$)}) {
            for my $qual (keys %decls) {
                my $d = $decls{$qual};
                next unless $d->{import_path} eq $local_import_path;
                next if $d->{kind} eq 'method';
                my $name = $d->{name};
                if ($line =~ /\b\Q$name\E\s*\(/ && $line !~ /^func\s+\Q$name\E\s*\(/ && $line !~ /^func\s+\([^)]+\)\s+\Q$name\E\s*\(/) {
                    record_call($local_import_path, $name, $caller, $file);
                }
            }
        }
    }
}

my %raw_calls;
my %unique_callers;

sub record_call {
    my ($ipath, $callee, $caller, $file) = @_;
    return unless $ipath =~ m{github\.com/usememos/memos/internal};

    for my $qual (keys %decls) {
        my $d = $decls{$qual};
        next unless $d->{import_path} eq $ipath;
        next unless $d->{name} eq $callee;
        $raw_calls{$qual}++;
        $unique_callers{$qual}{$caller} = 1;
    }
}

# Collect files
my @internal_files = `find '$repo/internal' -name '*.go' ! -name '*_test.go'`;
chomp @internal_files;
for my $f (@internal_files) { parse_decls($f); }

for my $d (values %decls) {
    $pkg_paths{$d->{import_path}}{$d->{pkg}} = 1;
}

my @all_go = `find '$repo' -name '*.go'`;
chomp @all_go;
for my $f (@all_go) { scan_calls($f); }

my @sorted = sort {
    (scalar keys %{$unique_callers{$b} || {}}) <=> (scalar keys %{$unique_callers{$a} || {}})
        || ($raw_calls{$b} || 0) <=> ($raw_calls{$a} || 0)
} keys %decls;

print "TOP 40 BY UNIQUE CALLERS:\n";
print "rank\tunique\traw\tqual\tpath:line\n";
my $rank = 0;
for my $qual (@sorted[0..39]) {
    $rank++;
    my $uc = scalar keys %{$unique_callers{$qual} || {}};
    my $rc = $raw_calls{$qual} || 0;
    my $d = $decls{$qual};
    print "$rank\t$uc\t$rc\t$qual\t$d->{path}:$d->{line}\n";
}

print "\nTOP 40 BY RAW CALLS:\n";
@sorted = sort { ($raw_calls{$b}||0) <=> ($raw_calls{$a}||0) || (scalar keys %{$unique_callers{$b}||{}}) <=> (scalar keys %{$unique_callers{$a}||{}}) } keys %decls;
$rank = 0;
for my $qual (@sorted[0..39]) {
    $rank++;
    my $uc = scalar keys %{$unique_callers{$qual} || {}};
    my $rc = $raw_calls{$qual} || 0;
    my $d = $decls{$qual};
    print "$rank\t$uc\t$rc\t$qual\t$d->{path}:$d->{line}\n";
}

# Winner detail
my $winner = $sorted[0];
print "\n=== WINNER (by raw): $winner ===\n";
my $d = $decls{$winner};
print "Path: $d->{path}:$d->{line}\n";
print "Import: $d->{import_path}\n";
print "Unique callers: " . scalar(keys %{$unique_callers{$winner}||{}}) . "\n";
print "Raw calls: " . ($raw_calls{$winner}||0) . "\n";
print "Callers:\n";
for my $c (sort keys %{$unique_callers{$winner}||{}}) { print "  $c\n"; }

# Also show winner by unique
@sorted = sort {
    (scalar keys %{$unique_callers{$b} || {}}) <=> (scalar keys %{$unique_callers{$a} || {}})
        || ($raw_calls{$b} || 0) <=> ($raw_calls{$a} || 0)
} grep { ($raw_calls{$_}||0) > 0 } keys %decls;
