value.beforeFullFileContent:
#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $repo = '/bench/repo';
my %decls;       # qual_name => { path, line, pkg, recv, name, kind }
my %pkg_paths;   # import_path => set of package names (usually one)
my %path_to_pkg; # file => package name

# --- Phase 1: collect declarations under internal/ ---
find({
    wanted => sub {
        return unless /\.go$/;
        return if /_test\.go$/;
        my $file = $File::Find::name;
        return unless $file =~ m{/internal/};
        parse_decls($file);
    },
    no_chdir => 1,
}, "$repo/internal");

sub parse_decls {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    my @lines = <$fh>;
    close $fh;

    my $pkg = '';
    for (@lines) {
        $pkg = $1 if /^package\s+(\w+)/;
    }
    $path_to_pkg{$file} = $pkg;

    my $i = 0;
    for my $line (@lines) {
        $i++;
        if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
            my ($ptr, $recv, $name) = ($1, $2, $3);
            my $qual = "$pkg.$recv.$name";
            $decls{$qual} = {
                path => $file, line => $i, pkg => $pkg,
                recv => $recv, name => $name, kind => 'method',
                import_path => import_path_for($file),
            };
        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
            my $name = $1;
            next if $name eq 'init';
            my $qual = "$pkg.$name";
            $decls{$qual} = {
                path => $file, line => $i, pkg => $pkg,
                recv => '', name => $name, kind => 'func',
                import_path => import_path_for($file),
            };
        }
    }
}

sub import_path_for {
    my ($file) = @_;
    $file =~ s{^\Q$repo\E/}{};
    $file =~ s/\.go$//;
    return "github.com/usememos/memos/$file";
}

# Build lookup: import_path -> package name
for my $d (values %decls) {
    $pkg_paths{$d->{import_path}}{$d->{pkg}} = 1;
}

# --- Phase 2: scan all Go files for call sites ---
my %raw_calls;    # qual => count
my %unique_callers; # qual => { caller_qual => 1 }

find({
    wanted => sub {
        return unless /\.go$/;
        my $file = $File::Find::name;
        scan_calls($file);
    },
    no_chdir => 1,
}, $repo);

sub scan_calls {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    my @lines = <$fh>;
    close $fh;

    my $pkg = '';
    my %imports;  # alias -> import_path
    my $in_import = 0;

    for my $line (@lines) {
        if ($line =~ /^package\s+(\w+)/) { $pkg = $1; next; }
        if ($line =~ /^import\s+\(/) { $in_import = 1; next; }
        if ($in_import) {
            if ($line =~ /^\)/) { $in_import = 0; next; }
            if ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = (split '/', $path)[-1];
                $imports{$alias} = $path;
            } elsif ($line =~ /^\s*(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            }
            next;
        }
        if ($line =~ /^import\s+"([^"]+)"/) {
            my $path = $1;
            my $alias = (split '/', $path)[-1];
            $imports{$alias} = $path;
        }
    }

    # Determine if this file is inside an internal package
    my $local_import_path = '';
    if ($file =~ m{\Q$repo\E/(.+)\.go$}) {
        my $rel = $1;
        $local_import_path = "github.com/usememos/memos/$rel";
        $local_import_path =~ s/\/[^\/]+$//;
    }

    my $current_func = '';
    my $current_recv = '';
    my $i = 0;

    for my $line (@lines) {
        $i++;
        if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
            $current_recv = $2;
            $current_func = $3;
        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
            $current_recv = '';
            $current_func = $1;
        }

        my $caller = $current_func ? ($current_recv ? "$pkg.$current_recv.$current_func" : "$pkg.$current_func") : "$file:$i";

        # Match alias.FuncName( or alias.MethodName(
        while ($line =~ /\b([a-zA-Z_]\w*)\.([a-zA-Z_]\w*)\s*\(/g) {
            my ($alias, $callee) = ($1, $2);
            next unless exists $imports{$alias};
            my $ipath = $imports{$alias};
            record_call($ipath, $alias, $callee, $caller, $file);
        }

        # Same-package unqualified calls (only for internal packages)
        if ($local_import_path =~ m{/internal(/|$)}) {
            for my $d (values %decls) {
                next unless $d->{import_path} eq $local_import_path;
                next if $d->{kind} eq 'method'; # skip unqualified method calls (ambiguous)
                my $name = $d->{name};
                next if $name =~ /^(init)$/;
                if ($line =~ /\b\Q$name\E\s*\(/ && $line !~ /^func\s+\Q$name\E\s*\(/ && $line !~ /^func\s+\([^)]+\)\s+\Q$name\E\s*\(/) {
                    record_call($local_import_path, $pkg, $name, $caller, $file);
                }
            }
        }

        # Method calls on common receivers: profile.AllowAnonymous, engine.Compile, etc.
        # Already covered by alias.Func for package-level; for methods on typed vars,
        # match recv.Method( where recv type maps to internal type - harder.
        # Also match (*Type).Method in interface satisfaction - skip.
    }
}

sub record_call {
    my ($ipath, $alias, $callee, $caller, $file) = @_;
    return unless $ipath =~ m{github\.com/usememos/memos/internal};

    # Skip if caller is the declaration itself (recursive)
    my @candidates;

    # Function: pkg.callee
    if (exists $pkg_paths{$ipath}) {
        for my $p (keys %{$pkg_paths{$ipath}}) {
            push @candidates, "$p.$callee";
            # Method on type with same name as package? unlikely
            for my $d (keys %decls) {
                next unless $decls{$d}{import_path} eq $ipath;
                next unless $decls{$d}{name} eq $callee;
                push @candidates, $d;
            }
        }
    }

    # Direct method: pkg.Type.callee when alias matches lowercase type var
    for my $d (keys %decls) {
        next unless $decls{$d}{import_path} eq $ipath;
        next unless $decls{$d}{name} eq $callee;
        push @candidates, $d;
    }

    my %seen;
    for my $qual (@candidates) {
        next unless exists $decls{$qual};
        next if $seen{$qual}++;
        # Exclude self-calls within same function
        next if $decls{$qual}{path} eq $file && $caller =~ /\.\Q$callee\E$/;
        $raw_calls{$qual}++;
        $unique_callers{$qual}{$caller} = 1;
    }
}

# --- Output top candidates ---
my @sorted = sort {
    (scalar keys %{$unique_callers{$b} || {}}) <=> (scalar keys %{$unique_callers{$a} || {}})
        || ($raw_calls{$b} || 0) <=> ($raw_calls{$a} || 0)
} keys %decls;

print "TOP 30 BY UNIQUE CALLERS:\n";
print "rank\tunique_callers\traw_calls\tqual_name\tpath:line\n";
my $rank = 0;
for my $qual (@sorted[0..29]) {
    $rank++;
    my $uc = scalar keys %{$unique_callers{$qual} || {}};
    my $rc = $raw_calls{$qual} || 0;
    my $d = $decls{$qual};
    print "$rank\t$uc\t$rc\t$qual\t$d->{path}:$d->{line}\n";
}

print "\nTOP 30 BY RAW CALLS:\n";
@sorted = sort { ($raw_calls{$b}||0) <=> ($raw_calls{$a}||0) } keys %decls;
$rank = 0;
for my $qual (@sorted[0..29]) {
    $rank++;
    my $uc = scalar keys %{$unique_callers{$qual} || {}};
    my $rc = $raw_calls{$qual} || 0;
    my $d = $decls{$qual};
    print "$rank\t$uc\t$rc\t$qual\t$d->{path}:$d->{line}\n";
}

# Detail for top candidate
