#!/usr/bin/perl
use strict;
use warnings;

my $repo = '/bench/repo';
my $include_tests = ($ARGV[0] // 'all') eq 'all';
my %decls;

sub import_path_for {
    my ($file) = @_;
    my $dir = $file;
    $dir =~ s{^\Q$repo\E/}{};
    $dir =~ s/\/[^\/]+\.go$//;
    return "github.com/usememos/memos/$dir";
}

sub is_test_file { $_[0] =~ /_test\.go$/ }

sub parse_decls {
    my ($file) = @_;
    return if is_test_file($file);
    open my $fh, '<', $file or return;
    my @lines = <$fh>; close $fh;
    my ($pkg) = grep /^package\s+(\w+)/, @lines;
    return unless defined $pkg;
    my $i = 0;
    for my $line (@lines) {
        $i++;
        if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($2, $3);
            $decls{"$pkg.$recv.$name"} = { path=>$file, line=>$i, pkg=>$pkg, recv=>$recv, name=>$name, kind=>'method', import_path=>import_path_for($file), exported => ($name =~ /^[A-Z]/) };
        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
            my $name = $1; next if $name eq 'init';
            $decls{"$pkg.$name"} = { path=>$file, line=>$i, pkg=>$pkg, name=>$name, kind=>'func', import_path=>import_path_for($file), exported => ($name =~ /^^[A-Z]/) };
        }
    }
}

my (%raw_calls, %unique_callers);

sub scan_calls {
    my ($file) = @_;
    return if !$include_tests && is_test_file($file);
    open my $fh, '<', $file or return;
    my @lines = <$fh>; close $fh;
    my ($pkg) = grep /^package\s+(\w+)/, @lines;
    $pkg //= '';
    my (%imports, $in_import);
    for my $line (@lines) {
        if ($line =~ /^import\s+\(/) { $in_import=1; next; }
        if ($in_import) {
            if ($line =~ /^\)/) { $in_import=0; next; }
            if ($line =~ /^\s*"([^"]+)"/) { $imports{(split '/',$1)[-1]}=$1; }
            elsif ($line =~ /^\s*(\w+)\s+"([^"]+)"/) { $imports{$1}=$2; }
            next;
        }
        if ($line =~ /^import\s+"([^"]+)"/) { $imports{(split '/',$1)[-1]}=$1; }
    }
    my $local_ip = '';
    if ($file =~ m{\Q$repo\E/(.+)\.go$}) { $local_ip = "github.com/usememos/memos/" . ($1 =~ s/\/[^\/]+$//r); }

    my ($current_func, $current_recv, $i) = ('','',0);
    for my $line (@lines) {
        $i++;
        if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) { ($current_recv,$current_func)=($2,$3); }
        elsif ($line =~ /^func\s+(\w+)\s*\(/) { ($current_recv,$current_func)=('',$1); }
        my $caller = $current_func ? ($current_recv ? "$pkg.$current_recv.$current_func" : "$pkg.$current_func") : "$file:$i";

        while ($line =~ /\b([a-zA-Z_]\w*)\.([a-zA-Z_]\w*)\s*\(/g) {
            record($imports{$1}, $2, $caller) if exists $imports{$1};
        }
        if ($local_ip =~ m{/internal}) {
            for my $q (keys %decls) {
                my $d = $decls{$q}; next unless $d->{import_path} eq $local_ip;
                next if $d->{kind} eq 'method';
                my $n = $d->{name};
                if ($line =~ /\b\Q$n\E\s*\(/ && $line !~ /^func\s+(\([^)]+\)\s+)?\Q$n\E\s*\(/) {
                    record($local_ip, $n, $caller);
                }
            }
        }
        # Method calls: .MethodName( for internal methods (any receiver var)
        while ($line =~ /\.([A-Z]\w*)\s*\(/g) {
            my $m = $1;
            for my $q (keys %decls) {
                my $d = $decls{$q};
                next unless $d->{kind} eq 'method' && $d->{name} eq $m;
                # Only count if file imports this package OR is same package
                my $ip = $d->{import_path};
                my $imports_pkg = 0;
                $imports_pkg = 1 if $local_ip eq $ip;
                for my $p (values %imports) { $imports_pkg = 1 if $p eq $ip; }
                next unless $imports_pkg;
                $raw_calls{$q}++; $unique_callers{$q}{$caller}=1;
            }
        }
    }
}

sub record {
    my ($ipath, $callee, $caller) = @_;
    return unless $ipath && $ipath =~ m{github\.com/usememos/memos/internal};
    for my $q (keys %decls) {
        my $d = $decls{$q};
        next unless $d->{import_path} eq $ipath && $d->{name} eq $callee;
        $raw_calls{$q}++; $unique_callers{$q}{$caller}=1;
    }
}

chomp(my @int = `find '$repo/internal' -name '*.go' ! -name '*_test.go'`);
$_->(), parse_decls($_) for @int;
chomp(my @go = `find '$repo' -name '*.go'`);
$_->(), scan_calls($_) for @go;

my @sorted = sort {
    (scalar keys %{$unique_callers{$b}||{}}) <=> (scalar keys %{$unique_callers{$a}||{}})
    || ($raw_calls{$b}||0) <=> ($raw_calls{$a}||0)
} grep { ($raw_calls{$_}||0) > 0 } keys %decls;

print "MODE: " . ($include_tests ? "all files" : "non-test only") . "\n";
print "TOP 25 (unique callers):\n";
my $r=0;
for my $q (@sorted[0..24]) {
    $r++;
    my $d=$decls{$q};
    printf "%d\t%d\t%d\t%s\t%s:%d\n", $r, scalar(keys %{$unique_callers{$q}}), $raw_calls{$q}, $q, $d->{path}, $d->{line};
}

