#!/usr/bin/perl
use strict;
use warnings;

my $repo = '/bench/repo';
my %decls;  # name => [{qual, path, line, kind}]

sub import_path_for {
    my ($file) = @_;
    my $dir = $file;
    $dir =~ s{^\Q$repo\E/}{};
    $dir =~ s/\/[^\/]+\.go$//;
    return "github.com/usememos/memos/$dir";
}

# Phase 1: collect declarations
for my $file (grep { !/_test\.go$/ } `find '$repo/internal' -name '*.go'`) {
    chomp $file;
    open my $fh, '<', $file or next;
    my @lines = <$fh>; close $fh;
    my ($pkg) = grep /^package\s+(\w+)/, @lines;
    next unless defined $pkg;
    my $i = 0;
    for my $line (@lines) {
        $i++;
        if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($2, $3);
            push @{$decls{$name}}, {
                qual => "$pkg.$recv.$name", path => $file, line => $i,
                kind => 'method', pkg => $pkg, recv => $recv,
            };
        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
            my $name = $1;
            next if $name eq 'init';
            push @{$decls{$name}}, {
                qual => "$pkg.$name", path => $file, line => $i,
                kind => 'func', pkg => $pkg,
            };
        }
    }
}

# Phase 2: for each unique name that appears in decls, count calls repo-wide
my %results;

for my $name (keys %decls) {
    my (%unique_callers, $raw);

    for my $file (`find '$repo' -name '*.go'`) {
        chomp $file;
        open my $fh, '<', $file or next;
        my @lines = <$fh>; close $fh;
        my ($pkg) = grep /^package\s+(\w+)/, @lines;
        my ($cf, $cr);

        for my $line (@lines) {
            if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
                ($cr, $cf) = ($2, $3);
            } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
                ($cr, $cf) = ('', $1);
            }

            my $matched = 0;
            # Qualified: alias.name(
            if ($line =~ /\b\w+\.\Q$name\E\s*\(/ && $line !~ /^func\s+(\([^)]+\)\s+)?\Q$name\E\s*\(/) {
                $matched = 1;
            }
            # Unqualified: name(
            elsif ($line =~ /\b\Q$name\E\s*\(/ && $line !~ /^func\s+(\([^)]+\)\s+)?\Q$name\E\s*\(/) {
                $matched = 1;
            }
            # Method: .name(
            elsif ($line =~ /\.\Q$name\E\s*\(/ && $line !~ /^func\s+\([^)]+\)\s+\Q$name\E\s*\(/) {
                $matched = 1;
            }

            if ($matched) {
                $raw++;
                my $caller = $cf ? ($cr ? "$pkg.$cr.$cf" : "$pkg.$cf") : "$file";
                $unique_callers{$caller} = 1;
            }
        }
    }

    for my $d (@{$decls{$name}}) {
        $results{$d->{qual}} = {
            %$d,
            raw => $raw,
            unique => scalar keys %unique_callers,
            # Note: raw/unique are per-NAME not per-decl; refined below for singletons
        };
    }
}

# Phase 3: precise per-declaration counting for top name collisions
sub count_precise {
    my ($name, $decl) = @_;
    my (%unique_callers, $raw);
    my $is_method = $decl->{kind} eq 'method';
    my $decl_pkg = $decl->{pkg};
    my $decl_file = $decl->{path};

    for my $file (`find '$repo' -name '*.go'`) {
        chomp $file;
        open my $fh, '<', $file or next;
        my @lines = <$fh>; close $fh;
        my ($pkg) = grep /^package\s+(\w+)/, @lines;

        # imports
        my (%imports, $in_imp);
        for my $line (@lines) {
            if ($line =~ /^import\s+\(/) { $in_imp=1; next; }
            if ($in_imp) {
                if ($line =~ /^\)/) { $in_imp=0; next; }
                if ($line =~ /^\s*"([^"]+)"/) { $imports{(split '/',$1)[-1]}=$1; }
                elsif ($line =~ /^\s*(\w+)\s+"([^"]+)"/) { $imports{$1}=$2; }
                next;
            }
            if ($line =~ /^import\s+"([^"]+)"/) { $imports{(split '/',$1)[-1]}=$1; }
        }

        my $local_ip = '';
        if ($file =~ m{\Q$repo\E/(.+)\.go$}) {
            $local_ip = "github.com/usememos/memos/" . ($1 =~ s/\/[^\/]+$//r);
        }
        my $decl_ip = import_path_for($decl_file);

        my ($cf, $cr);
        for my $line (@lines) {
            if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
                ($cr, $cf) = ($2, $3);
            } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
                ($cr, $cf) = ('', $1);
            }

            next if $line =~ /^func\s+(\([^)]+\)\s+)?\Q$name\E\s*\(/;

            my $hit = 0;

            # Package-qualified call
            while ($line =~ /\b([a-zA-Z_]\w*)\.\Q$name\E\s*\(/g) {
                my $alias = $1;
                if (exists $imports{$alias}) {
                    my $ip = $imports{$alias};
                    $hit = 1 if $ip eq $decl_ip;
                } elsif ($alias eq $decl_pkg && $local_ip eq $decl_ip) {
                    $hit = 1;
                }
            }

            # Unqualified (same package only)
            if (!$hit && $local_ip eq $decl_ip && !$is_method) {
                $hit = 1 if $line =~ /\b\Q$name\E\s*\(/;
            }

            # Method call .Name( - if file imports decl package or same package
            if (!$hit && $is_method) {
                my $imports_decl = ($local_ip eq $decl_ip);
                for (values %imports) { $imports_decl = 1 if $_ eq $decl_ip; }
                if ($imports_decl && $line =~ /\.\Q$name\E\s*\(/) {
                    $hit = 1;
                }
            }

            if ($hit) {
                $raw++;
                my $caller = $cf ? ($cr ? "$pkg.$cr.$cf" : "$pkg.$cf") : "$file";
                $unique_callers{$caller} = 1;
            }
        }
    }
    return ($raw, scalar keys %unique_callers, \%unique_callers);
}

# Precise count for all declarations
my @precise;
for my $name (keys %decls) {
    for my $d (@{$decls{$name}}) {
        my ($raw, $unique, $callers) = count_precise($name, $d);
        push @precise, { %$d, raw => $raw, unique => $unique, callers => $callers };
    }
}

@precise = sort { $b->{unique} <=> $a->{unique} || $b->{raw} <=> $a->{raw} } @precise;

print "TOP 30 BY UNIQUE CALLERS (precise per-declaration):\n";
printf "rank\tunique\traw\tqual\tpath:line\n";
my $r = 0;
for my $p (@precise[0..29]) {
    $r++;
    printf "%d\t%d\t%d\t%s\t%s:%d\n", $r, $p->{unique}, $p->{raw}, $p->{qual}, $p->{path}, $p->{line};
}

my $w = $precise[0];
print "\n=== WINNER ===\n";
print "Qual: $w->{qual}\n";
print "Path: $w->{path}:$w->{line}\n";
print "Unique callers: $w->{unique}\n";
print "Raw call expressions: $w->{raw}\n";
print "\nAll callers:\n";
for my $c (sort keys %{$w->{callers}}) { print "  $c\n"; }

# Stats
print "\nTotal declarations scanned: ", scalar(@precise), "\n";

