#!/usr/bin/perl
use strict;
use warnings;

my $repo = '/bench/repo';

# Build declarations: list of { qual, name, path, line, ipath, pkg, kind, recv }
my @decls;

sub dir_to_ipath {
    my ($file) = @_;
    my $d = $file; $d =~ s{^\Q$repo\E/}{}; $d =~ s/\/[^\/]+\.go$//;
    return "github.com/usememos/memos/$d";
}

for my $file (grep { !/_test\.go$/ } `find '$repo/internal' -name '*.go'`) {
    chomp $file;
    open my $fh, '<', $file or next;
    my @lines = <$fh>; close $fh;
    my ($pkg) = grep { /^package\s+(\w+)/ && ($pkg=$1) } @lines;
    next unless $pkg;
    my $ip = dir_to_ipath($file);
    my $i = 0;
    for my $line (@lines) {
        $i++;
        if ($line =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) {
            push @decls, {
                qual => "$pkg.$2.$3", name => $3, path => $file, line => $i,
                ipath => $ip, pkg => $pkg, kind => 'method', recv => $2,
            };
        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
            my $n = $1; next if $n eq 'init';
            push @decls, {
                qual => "$pkg.$n", name => $n, path => $file, line => $i,
                ipath => $ip, pkg => $pkg, kind => 'func',
            };
        }
    }
}

print "Parsed ", scalar(@decls), " declarations\n";

sub count_decl {
    my ($d) = @_;
    my ($raw, %callers);
    my $name = $d->{name};
    my $ip = $d->{ipath};
    my $pkg = $d->{pkg};
    my $is_method = $d->{kind} eq 'method';

    for my $file (`find '$repo' -name '*.go'`) {
        chomp $file;
        open my $fh, '<', $file or next;
        my @lines = <$fh>; close $fh;
        my ($fpkg) = grep { /^package\s+(\w+)/ && ($fpkg=$1) } @lines;

        my (%imports, $in);
        for my $l (@lines) {
            if ($l =~ /^import\s+\(/) { $in=1; next; }
            if ($in) { if ($l =~ /^\)/) { $in=0; next; }
                if ($l =~ /^\s*"([^"]+)"/) { $imports{(split '/',$1)[-1]}=$1; }
                elsif ($l =~ /^\s*(\w+)\s+"([^"]+)"/) { $imports{$1}=$2; }
                next;
            }
            if ($l =~ /^import\s+"([^"]+)"/) { $imports{(split '/',$1)[-1]}=$1; }
        }
        my $local_ip = dir_to_ipath($file);
        my $imports_target = ($local_ip eq $ip);
        for (values %imports) { $imports_target = 1 if $_ eq $ip; }

        my ($cf, $cr);
        for my $l (@lines) {
            if ($l =~ /^func\s+\((?:\([^)]+\)\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/) { ($cr,$cf)=($2,$3); }
            elsif ($l =~ /^func\s+(\w+)\s*\(/) { ($cr,$cf)=('',$1); }
            next if $l =~ /^func\s+(\([^)]+\)\s+)?\Q$name\E\s*\(/;

            my $hit = 0;
            # pkg-qualified: alias.name( or same-package pkg.name(
            while ($l =~ /\b([a-zA-Z_]\w*)\.\Q$name\E\s*\(/g) {
                my $a = $1;
                if ((exists $imports{$a} && $imports{$a} eq $ip) || ($a eq $pkg && $local_ip eq $ip)) {
                    $hit = 1; last;
                }
            }
            if (!$hit && !$is_method && $local_ip eq $ip && $l =~ /\b\Q$name\E\s*\(/) {
                $hit = 1;
            }
            if (!$hit && $is_method && $imports_target && $l =~ /\.\Q$name\E\s*\(/) {
                $hit = 1;
            }
            if ($hit) {
                $raw++;
                my $caller = $cf ? ($cr ? "$fpkg.$cr.$cf" : "$fpkg.$cf") : "$file";
                $callers{$caller} = 1;
            }
        }
    }
    return ($raw, scalar keys %callers, \%callers);
}

my @results;
for my $d (@decls) {
    my ($raw, $unique, $callers) = count_decl($d);
    next unless $unique > 0;
    push @results, { %$d, raw => $raw, unique => $unique, callers => $callers };
}

@results = sort { $b->{unique} <=> $a->{unique} || $b->{raw} <=> $a->{raw} } @results;

print "\nTOP 15:\n";
printf "uniq\traw\tqual\tpath:line\n";
for (@results[0..14]) {
    printf "%d\t%d\t%s\t%s:%d\n", $_->{unique}, $_->{raw}, $_->{qual}, $_->{path}, $_->{line};
}

my $w = $results[0];
print "\n=== CHAMPION: $w->{qual} ===\n";
print "File: $w->{path}:$w->{line}\n";
print "Unique callers: $w->{unique}\n";
print "Raw calls: $w->{raw}\n";

# breakdown test vs non-test callers
my ($test_c, $prod_c) = (0, 0);
for my $c (keys %{$w->{callers}}) {
    if ($c =~ /Test|Example|test|memoEngineAt/) { $test_c++ } else { $prod_c++ }
}
print "Test callers: $test_c, Non-test callers: $prod_c\n";

# Show #2 for comparison
my $s = $results[1];
print "\n=== RUNNER-UP: $s->{qual} ===\n";
print "File: $s->{path}:$s->{line}\n";
print "Unique callers: $s->{unique}, Raw calls: $s->{raw}\n";

