perl -e '
use strict; my $repo="/bench/repo";
sub dir_to_ipath { my($f)=@_; $f=~s{^\Q$repo\E/}{}; $f=~s/\/[^\/]+\.go$//; "github.com/usememos/memos/$f" }
my %c; my $raw=0;
for my $file (`find $repo -name "*.go"`) {
  chomp $file; open my $fh,"<",$file or next; my @lines=<$fh>; close $fh;
  my $fpkg=""; for(@lines){/^package\s+(\w+)/ and $fpkg=$1 and last}
  my (%imports,$in); for my $l (@lines){
    if($l=~/^import\s+\(/){$in=1;next} if($in){if($l=~/^\)/){$in=0;next}
      if($l=~/^\s*"([^"]+)"/){$imports{(split"/",$1)[-1]}=$1} elsif($l=~/^\s*(\w+)\s+"([^"]+)"/){$imports{$1}=$2} next}
    if($l=~/^import\s+"([^"]+)"/){$imports{(split"/",$1)[-1]}=$1}
  }
  my $local=dir_to_ipath($file); my $it=0; $it=1 if $local eq "github.com/usememos/memos/internal/filter";
  for(values %imports){$it=1 if $_ eq "github.com/usememos/memos/internal/filter"}
  my ($cf,$cr); for my $l (@lines){
    if($l=~/^func\s+(?:\([^)]+\)\s+)?\((\w+\s+)?(\*?)(\w+)\)\s+(\w+)\s*\(/){($cr,$cf)=($3,$4)}
    elsif($l=~/^func\s+(\w+)\s*\(/){($cr,$cf)=("",$1)}
    next if $l=~/^func\s+(\([^)]+\)\s+)?CompileToStatement\s*\(/;
    if($it && $l=~/\.CompileToStatement\s*\(/){ $raw++; my $caller=$cf?($cr?"$fpkg.$cr.$cf":"$fpkg.$cf"):$file; push @{$c{$caller}}, $file }
  }
}
print "Raw: $raw\nUnique: ",scalar(keys %c),"\n\n";
for my $k (sort keys %c) {
  my $test = ($k =~ /Test|Example|memoEngineAt/ || (grep {/_test\.go$/} @{$c{$k}})) ? "TEST" : "PROD";
  print "$test\t$k\t", join(",", @{$c{$k}}), "\n";
}
'

